package com.olenanoskova.task_and_time_tracker.service;import com.olenanoskova.task_and_time_tracker.repository.NotificationRepository;import com.olenanoskova.task_and_time_tracker.mapper.NotificationMapper;import org.junit.jupiter.api.Test;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.InjectMocks;import org.mockito.Mock;import org.mockito.junit.jupiter.MockitoExtension;import java.util.UUID;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;@ExtendWith(MockitoExtension.class) class NotificationServiceTest{ @Mock NotificationRepository repo; @Mock NotificationMapper mapper; @InjectMocks NotificationServiceImpl service; @Test void getById_notFound_throws(){ UUID id=UUID.randomUUID(); when(repo.findById(id)).thenReturn(java.util.Optional.empty()); assertThrows(RuntimeException.class,()->service.getNotificationById(id)); } }
